from registry import register, get

class BasicRenderer:
    def render(self, value): return f'basic:{value}'

class ComposedRenderer:
    def __init__(self, base): self.base = base
    def render(self, value): return f'composed[{self.base.render(value)}]'

def install():
    register('basic', BasicRenderer)
    register('composed', lambda: ComposedRenderer(get('basic')))

