class EventBus:
    def __init__(self): self._callbacks=[]
    def subscribe(self, callback): self._callbacks.append(callback)
    def unsubscribe(self, callback):
        self._callbacks=[item for item in self._callbacks if item is not callback]
    def emit(self, value):
        for callback in list(self._callbacks): callback(value)
    def subscriber_count(self): return len(self._callbacks)

